const { Firestore } = require('@google-cloud/firestore');
const fs = require('fs');

async function run() {
  const firestore = new Firestore({ projectId: 'mocktest-7d23a' });
  console.log("🔍 Scanning all collections dynamically...");

  try {
    const collections = await firestore.listCollections();
    let totalBytes = 0;

    console.log("==================================================");
    for (const col of collections) {
      const snapshot = await col.get();
      let colBytes = 0;

      snapshot.forEach(doc => {
        colBytes += Buffer.byteLength(JSON.stringify(doc.data()));
      });

      const colKb = (colBytes / 1024).toFixed(2);
      console.log(`📦 ${col.id.padEnd(25)} : ${colKb} KB`);
      totalBytes += colBytes;
    }

    console.log("==================================================");
    console.log(`📊 TOTAL PROJECT USAGE : ${(totalBytes / 1024).toFixed(2)} KB`);
    console.log("==================================================");
  } catch (err) {
    console.error("Error scanning project:", err.message);
  }
}
run();
EOF
